1279→// outputWithPager outputs content through a pager if stdout is a terminal and content is long.
1280→func outputWithPager(w io.Writer, content string) {
1281→	// Check if we're writing to stdout and it's a terminal
1282→	if f, ok := w.(*os.File); ok && f == os.Stdout && term.IsTerminal(int(f.Fd())) {
1283→		// Get terminal height
1284→		_, height, err := term.GetSize(int(f.Fd()))
1285→		if err != nil {
1286→			height = 24 // Default fallback
1287→		}
1288→
1289→		// Count lines in content
1290→		lineCount := strings.Count(content, "\n")
1291→
1292→		// Use pager if content exceeds terminal height
1293→		if lineCount > height-2 {
1294→			pager := os.Getenv("PAGER")
1295→			if pager == "" {
1296→				pager = "less"
1297→			}
1298→
1299→			cmd := exec.CommandContext(context.Background(), pager) //nolint:gosec // pager from env is expected
1300→			cmd.Stdin = strings.NewReader(content)
1301→			cmd.Stdout = f
1302→			cmd.Stderr = os.Stderr
1303→
1304→			if err := cmd.Run(); err != nil {
1305→				// Fallback to direct output if pager fails
1306→				fmt.Fprint(w, content)
1307→			}
1308→			return
1309→		}
1310→	}
1311→
1312→	// Direct output for non-terminal or short content
1313→	fmt.Fprint(w, content)
1314→}
