1352→// Exported for use by strategy package (session_test.go)
1353→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
1354→	obj := repo.Storer.NewEncodedObject()
1355→	obj.SetType(plumbing.BlobObject)
1356→	obj.SetSize(int64(len(content)))
1357→
1358→	writer, err := obj.Writer()
1359→	if err != nil {
1360→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
1361→	}
1362→
1363→	_, err = writer.Write(content)
1364→	if err != nil {
1365→		_ = writer.Close()
1366→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
1367→	}
1368→	if err := writer.Close(); err != nil {
1369→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
1370→	}
1371→
1372→	hash, err := repo.Storer.SetEncodedObject(obj)
1373→	if err != nil {
1374→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
1375→	}
1376→	return hash, nil
1377→}
