+// fetchAndFindCheckpoint attempts to fetch the metadata branch from remote and find a checkpoint.
+// This handles the case where entire/checkpoints/v1 exists on the remote but not locally
+// (e.g., fresh clone where the branch wasn't fetched or remote-tracking ref is missing).
+func fetchAndFindCheckpoint(checkpointIDPrefix string) (id.CheckpointID, error) {
+	fmt.Fprintf(os.Stderr, "Fetching session metadata from origin...\n")
+	if err := FetchMetadataBranch(); err != nil {
+		return "", fmt.Errorf("failed to fetch metadata branch: %w", err)
+	}
+
+	// Re-open repo to pick up new refs after fetch
+	repo, err := openRepository()
+	if err != nil {
+		return "", fmt.Errorf("failed to open repository: %w", err)
+	}
+
+	store := checkpoint.NewGitStore(repo)
+	committed, err := store.ListCommitted(context.Background())
+	if err != nil {
+		return "", fmt.Errorf("failed to list checkpoints after fetch: %w", err)
+	}
+
+	for _, info := range committed {
+		if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
+			return info.CheckpointID, nil
+		}
+	}
+
+	return "", fmt.Errorf("checkpoint not found after fetch: %s", checkpointIDPrefix)
+}
